#include <unistd.h>
#include <stdio.h>
#include <stdlib.h>
#define NALLOC 1024
void *morecore(unsigned nu) {
  void *ptr = sbrk(nu * sizeof(char));
  if (ptr == (void*)-1) {
    perror("sbrk failed");
    exit(1);
  }
  return ptr;
}
int main() {
  char *p = (char *) morecore(NALLOC);
  if (p == NULL) {
     fprintf(stderr, "Memory allocation failed\n");
     return 1;
  }
  printf("Allocated %d bytes at address %p\n", NALLOC, p);
  // ... use the allocated memory ...
  return 0;
}
